308	    beginInfo.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
309	
310	    VkResult r = vkBeginCommandBuffer(p->cmdBuf, &beginInfo);
311	    if (r != VK_SUCCESS) {
312	        return r;
313	    }
314	
315	    vkCmdBindPipeline(p->cmdBuf, VK_PIPELINE_BIND_POINT_COMPUTE, p->pipeline);
316	    vkCmdBindDescriptorSets(p->cmdBuf, VK_PIPELINE_BIND_POINT_COMPUTE, p->pipelineLayout, 0, 1, &p->descSet, 0, NULL);
317	    vkCmdDispatch(p->cmdBuf, groupsX, 1, 1);
318	
319	    r = vkEndCommandBuffer(p->cmdBuf);
320	    if (r != VK_SUCCESS) {
321	        return r;
322	    }
323	
324	    VkSubmitInfo submitInfo = {0};
325	    submitInfo.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
326	    submitInfo.commandBufferCount = 1;
327	    submitInfo.pCommandBuffers = &p->cmdBuf;
328	
329	    r = vkQueueSubmit(queue, 1, &submitInfo, p->fence);
330	    if (r != VK_SUCCESS) {
331	        return r;
332	    }
333	
334	    return vkWaitForFences(device, 1, &p->fence, VK_TRUE, 5000000000ULL);
