#version 450

layout(local_size_x = 64) in;

layout(binding = 0) buffer Data {
    float values[];
};

void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= values.length()) {
        return;
    }
    values[idx] = values[idx] * 2.0;
}

