VkResult shim_query_cooperative_matrix_properties(VkPhysicalDevice phys, ShimCoopMatProperty *out, uint32_t max, uint32_t *count) {
    uint32_t total = 0;
    VkResult r = vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR(phys, &total, NULL);
    if (r != VK_SUCCESS) {
        *count = 0;
        return r;
    }
    if (total == 0) {
        *count = 0;
        return VK_SUCCESS;
    }

    VkCooperativeMatrixPropertiesKHR *props = calloc(total, sizeof(*props));
    if (!props) {
        return VK_ERROR_OUT_OF_HOST_MEMORY;
    }
    for (uint32_t i = 0; i < total; i++) {
        props[i].sType = VK_STRUCTURE_TYPE_COOPERATIVE_MATRIX_PROPERTIES_KHR;
    }

    r = vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR(phys, &total, props);

