		if err != nil {
			return nil, fmt.Errorf("softmax shared size=%d: %w", n, err)
		}
		results = append(results, r)

		r, err = runSoftmax(dev, smSub, "subgroup", 64, n, warmup, iters)
		if err != nil {
			return nil, fmt.Errorf("softmax subgroup size=%d: %w", n, err)
		}
		results = append(results, r)
	}
	return results, nil
}

const rmsEps = float32(1e-6)

func runRMSNorm(dev *vk.Device, mod *vk.ShaderModule, variant string, localSize, n int, warmup, iters uint32) (Result, error) {
	rows := reduceRows
