// float32ToFloat16 converts f to IEEE754 binary16 bits. Values too small to
// represent as a normal half are flushed to zero rather than represented as
// half-subnormals — fine for this benchmark's data ranges (weights/scales
// drawn from [-1,1], never near the half-subnormal threshold).
func float32ToFloat16(f float32) uint16 {
	bits := math.Float32bits(f)
	sign := uint16((bits >> 16) & 0x8000)
	exp := int32((bits>>23)&0xFF) - 127 + 15
	mant := bits & 0x7FFFFF

	if exp <= 0 {
		return sign
	}
	if exp >= 0x1F {
		return sign | 0x7C00
	}
	return sign | uint16(exp<<10) | uint16(mant>>13)
}

